'use strict';
const vocabularyCourseCategories=['001','011','003','044','021','004','063','031','085','073','012','047','018','028','061','033','060','078','093','100'];
learningSkills.find(s=>s.id==='language').courses.unshift({id:'everyday-word-pictures',title:'Meet everyday words in pictures',level:'Vocabulary & shared play',need:'Your child benefits from clear pictures, adult modelling and a wider range of familiar words.',goal:'Connect everyday object names with recognisable pictures and real examples through naming, choosing, collecting, pairing and grouping.',props:'A grown-up, the child’s usual speech/sign/AAC support, and optional familiar real objects or photographs',notice:['Which objects your child recognises across different examples','Which names or signs your child chooses to share','Whether fewer pictures, modelling, or a real object helps'],home:'Choose a few useful words from a real routine, such as getting dressed or preparing a snack. Name or sign each object while using it. Return to pictures or photographs as reminders, keeping the child’s AAC available.',activities:vocabularyCourseCategories.map((category,index)=>({engine:'vocabulary',category,mode:['explore','find','collect','pairs','sort'][index%5],index}))});
